	if cmd.capture != "test" {
		t.Errorf("Expected capture to be 'test', got '%v'", cmd.capture)
	}
	if cmd.static != true {
		t.Errorf("Expected static to be true, got '%v'", cmd.static)
	}
	if cmd.unredacted != true {
		t.Errorf("Expected unredacted to be true, got '%v'", cmd.unredacted)
	}
